import { formatError, formatHelp } from './cli-format.mjs';
import { getProgramName } from './program-name.mjs';

function createHelpResult(programName) {
  return {
    type: 'help',
    stdout: formatHelp(programName),
  };
}

function createErrorResult(programName, message) {
  return {
    type: 'error',
    exitCode: 2,
    stderr: formatError(programName, message),
  };
}

function classifyLongHelpToken(token) {
  const equalsIndex = token.indexOf('=');
  const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);

  if (optionToken.length < 3 || !'--help'.startsWith(optionToken)) {
    return null;
  }

  if (equalsIndex !== -1) {
    return {
      type: 'error',
      message: `argument -h/--help: ignored explicit argument '${token.slice(equalsIndex + 1)}'`,
    };
  }

  return {
    type: 'help',
  };
}

function classifyShortHelpToken(token) {
  if (!token.startsWith('-h')) {
    return null;
  }

  if (token.startsWith('-h=')) {
    return {
      type: 'error',
      message: `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
    };
  }

  return {
    type: 'help',
  };
}

function classifyHelpToken(token) {
  if (!token.startsWith('-') || token === '-') {
    return null;
  }

  if (token.startsWith('--')) {
    return classifyLongHelpToken(token);
  }

  return classifyShortHelpToken(token);
}

function isOptionLike(token) {
  return token.length > 1 && token.startsWith('-');
}

function isSeparateValueToken(token) {
  return token === '-' || !isOptionLike(token);
}

function shouldAttachUnknownValue(token) {
  return token === '' || token === '-' || !isOptionLike(token);
}

export function parseCommandLine(argv) {
  const programName = getProgramName(argv);
  const tokens = argv.slice(2);
  const unrecognized = [];
  let value = null;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];
    const helpToken = classifyHelpToken(token);

    if (helpToken !== null) {
      if (helpToken.type === 'help') {
        return createHelpResult(programName);
      }

      return createErrorResult(programName, helpToken.message);
    }

    if (token === '--a') {
      const nextToken = tokens[index + 1];

      if (nextToken === undefined || !isSeparateValueToken(nextToken)) {
        return createErrorResult(programName, 'argument --a: expected one argument');
      }

      value = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      value = token.slice(4);
      continue;
    }

    unrecognized.push(token);

    const nextToken = tokens[index + 1];

    if (nextToken !== undefined && shouldAttachUnknownValue(nextToken)) {
      unrecognized.push(nextToken);
      index += 1;
    }
  }

  if (value === null) {
    return createErrorResult(programName, 'the following arguments are required: --a');
  }

  if (unrecognized.length > 0) {
    return createErrorResult(programName, `unrecognized arguments: ${unrecognized.join(' ')}`);
  }

  return {
    type: 'success',
    value,
  };
}

